SELECT CAST(medicare2_2.npi AS BIGINT) AS npi,   medicare2_2.nppes_credentials AS nppes_credentials,   medicare2_2.nppes_provider_city AS nppes_provider_city,   medicare2_2.nppes_provider_first_name AS nppes_provider_first_name,   medicare2_2.nppes_provider_last_org_name AS nppes_provider_last_org_name,   medicare2_2.nppes_provider_street1 AS nppes_provider_street1,   CAST(medicare2_2.nppes_provider_zip AS BIGINT) AS nppes_provider_zip,   SUM((CAST(medicare2_2.average_medicare_payment_amt AS double precision) * CAST(CAST(medicare2_2.line_srvc_cnt AS BIGINT) AS double precision))) AS sum_calculation_5520413173637078_ok,   SUM(CAST(medicare2_2.bene_unique_cnt AS BIGINT)) AS sum_bene_unique_cnt_ok,   SUM(CAST(medicare2_2.line_srvc_cnt AS BIGINT)) AS sum_line_srvc_cnt_ok FROM medicare2_2 WHERE ((medicare2_2.nppes_provider_state = 'NY') AND (medicare2_2.nppes_provider_country = 'US') AND (medicare2_2.provider_type = 'Allergy/Immunology')) GROUP BY medicare2_2.npi,   medicare2_2.nppes_credentials,   medicare2_2.nppes_provider_city,   medicare2_2.nppes_provider_first_name,   medicare2_2.nppes_provider_last_org_name,   medicare2_2.nppes_provider_street1,   medicare2_2.nppes_provider_zip,   npi,   nppes_provider_zip;
